    /// Return the document tag map and its distinct tag projection from one
    /// scoped population. Selected reads retain only exact Memory/Page owners.
    pub async fn list_tags_scoped(&self, scope: &ReadScope) -> Result<ScopedTags, WenlanError> {
        let (sql, values) = match scope {
            ReadScope::Global => (
                "SELECT source, source_id, tag
                   FROM document_tags
                  ORDER BY source, source_id, tag"
                    .to_string(),
                Vec::new(),
            ),
            ReadScope::Space(space) => (
                "SELECT dt.source, dt.source_id, dt.tag
                   FROM document_tags dt
                  WHERE (dt.source = 'memory' AND EXISTS (
                            SELECT 1 FROM memories m
                             WHERE m.source = dt.source
                               AND m.source_id = dt.source_id
                               AND m.space = ?1
                               AND NOT EXISTS (
                                   SELECT 1 FROM memories other
                                    WHERE other.source = dt.source
                                      AND other.source_id = dt.source_id
                                      AND (other.space IS NULL OR other.space <> ?1)
                               )
                        ))
                     OR (dt.source = 'page' AND EXISTS (
                            SELECT 1 FROM pages p
                             WHERE p.id = dt.source_id
                               AND p.workspace = ?1
                        ))
                  ORDER BY dt.source, dt.source_id, dt.tag"
                    .to_string(),
                vec![libsql::Value::Text(space.clone())],
            ),
            ReadScope::Uncategorized => (
                "SELECT dt.source, dt.source_id, dt.tag
                   FROM document_tags dt
                  WHERE (dt.source = 'memory' AND EXISTS (
                            SELECT 1 FROM memories m
                             WHERE m.source = dt.source
                               AND m.source_id = dt.source_id
                               AND (m.space IS NULL OR m.space = '00000000-0000-4000-8000-000000000001')
                               AND NOT EXISTS (
                                   SELECT 1 FROM memories other
                                    WHERE other.source = dt.source
                                      AND other.source_id = dt.source_id
                                      AND other.space IS NOT NULL
                                      AND other.space != '00000000-0000-4000-8000-000000000001'
                               )
                        ))
                     OR (dt.source = 'page' AND EXISTS (
                            SELECT 1 FROM pages p
                             WHERE p.id = dt.source_id
                               AND p.workspace = '00000000-0000-4000-8000-000000000001'
                        ))
                  ORDER BY dt.source, dt.source_id, dt.tag"
                    .to_string(),
                Vec::new(),
            ),
        };

        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(&sql, libsql::params_from_iter(values))
            .await
            .map_err(|e| WenlanError::VectorDb(format!("list_tags_scoped: {e}")))?;
        let mut tags = std::collections::BTreeSet::new();
        let mut document_tags: HashMap<String, Vec<String>> = HashMap::new();
        while let Some(row) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(format!("list_tags_scoped row: {e}")))?
        {
            let source: String = row.get(0).unwrap_or_default();
            let source_id: String = row.get(1).unwrap_or_default();
            let tag: String = row.get(2).unwrap_or_default();
            tags.insert(tag.clone());
            document_tags
                .entry(format!("{source}::{source_id}"))
                .or_default()
                .push(tag);
        }
        Ok(ScopedTags {
            tags: tags.into_iter().collect(),
            document_tags,
        })
    }

    /// Get memories that need re-embedding (structured content was set but embedding is stale).
    pub async fn get_reembed_candidates(
        &self,
        limit: usize,
    ) -> Result<Vec<(String, String)>, WenlanError> {
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT id, content, source_text, structured_fields FROM memories
                 WHERE needs_reembed = 1 AND source = 'memory'
                 ORDER BY last_modified DESC LIMIT ?1",
                libsql::params![limit as i64],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("get_reembed_candidates: {}", e)))?;
        let mut results = Vec::new();
        while let Ok(Some(row)) = rows.next().await {
            let id: String = row.get(0).unwrap_or_default();
            let content: String = row.get(1).unwrap_or_default();
            let source_text: Option<String> = row.get::<Option<String>>(2).unwrap_or(None);
            let _sf: Option<String> = row.get::<Option<String>>(3).unwrap_or(None);
            // Embed from prose when available (natural language embeds better)
            let embed_text = source_text.unwrap_or(content);
            results.push((id, embed_text));
        }
        Ok(results)
    }

    /// Get memories that need re-embedding, keyed by source_id (needs_reembed = 1).
    pub async fn get_pending_reembeds(
        &self,
        limit: usize,
    ) -> Result<Vec<PendingReembed>, WenlanError> {
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT id, source_id, content, source_text FROM memories
                 WHERE needs_reembed = 1 AND source = 'memory'
                 ORDER BY last_modified DESC LIMIT ?1",
                libsql::params![limit as i64],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("get_pending_reembeds: {}", e)))?;
        let mut results = Vec::new();
        while let Ok(Some(row)) = rows.next().await {
            let chunk_id: String = row.get(0).unwrap_or_default();
            let source_id: String = row.get(1).unwrap_or_default();
            let content: String = row.get(2).unwrap_or_default();
            let source_text: Option<String> = row.get::<Option<String>>(3).unwrap_or(None);
            let embed_text = source_text.unwrap_or_else(|| content.clone());
            results.push(PendingReembed {
                chunk_id,
                source_id,
                embed_text,
            });
        }
        Ok(results)
    }

    /// Re-embed a single memory with fresh embedding from its current content.
    pub async fn reembed_memory(&self, chunk_id: &str, content: &str) -> Result<(), WenlanError> {
        let embeddings = self.generate_embeddings(&[content.to_string()])?;
        if embeddings.is_empty() {
            return Err(WenlanError::VectorDb("empty embedding result".into()));
        }
        let conn = self.conn.lock().await;
        conn.execute(
            "UPDATE memories SET embedding = vector32(?1), enrichment_status = 'legacy', needs_reembed = 0 WHERE id = ?2",
            libsql::params![Self::vec_to_sql(&embeddings[0]), chunk_id],
        )
        .await
        .map_err(|e| WenlanError::VectorDb(format!("reembed_memory: {}", e)))?;
        Ok(())
    }

    /// Get memories that need classification (memory_type IS NULL).
    /// Returns (source_id, content) pairs grouped by source_id so each memory is
    /// processed exactly once, even when chunked into multiple rows.
    pub async fn get_unclassified_imports(
        &self,
        limit: usize,
    ) -> Result<Vec<(String, String)>, WenlanError> {
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT source_id, GROUP_CONCAT(content, ' ') as combined_content
                 FROM memories
                 WHERE source = 'memory'
                   AND memory_type IS NULL
                 GROUP BY source_id
                 ORDER BY MAX(last_modified) DESC
                 LIMIT ?1",
                libsql::params![limit as i64],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?;

        let mut results = Vec::new();
        while let Some(row) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            let source_id: String = row
                .get(0)
                .map_err(|e| WenlanError::VectorDb(e.to_string()))?;
            let content: String = row
                .get(1)
                .map_err(|e| WenlanError::VectorDb(e.to_string()))?;
            results.push((source_id, content));
        }
        Ok(results)
    }

    /// Get the current memory_type and space for a source_id (first chunk).
    pub async fn get_memory_classification(
        &self,
        source_id: &str,
    ) -> Result<(Option<String>, Option<String>), WenlanError> {
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT memory_type, space FROM memories WHERE source_id = ?1 LIMIT 1",
                libsql::params![source_id],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?;
        if let Some(row) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            let memory_type: Option<String> = row.get(0).ok();
            // M3 PR-1 stage e: memories.space is NOT NULL as of migration
            // 85, so an unscoped memory carries the reserved sentinel id
            // rather than NULL -- translate it back to None here so callers
            // (test-only; see caller inventory) that treat None as
            // "no space" keep working.
            let space: Option<String> = row
                .get::<Option<String>>(1)
                .ok()
                .flatten()
                .filter(|s| s != UNFILED_SPACE_ID);
            Ok((memory_type, space))
        } else {
            Ok((None, None))
        }
    }

    /// Update the memory_type for all memories with a given source_id.
    pub async fn update_memory_type(
        &self,
        source_id: &str,
        memory_type: &str,
    ) -> Result<(), WenlanError> {
        self.apply_memory_update(source_id, None, None, false, Some(memory_type), None)
            .await
    }

    pub async fn update_memory_space(
        &self,
        source_id: &str,
        space: &str,
    ) -> Result<(), WenlanError> {
        self.update_memory_space_opt(source_id, Some(space)).await
    }

    pub async fn update_memory_space_opt(
        &self,
        source_id: &str,
        space: Option<&str>,
    ) -> Result<(), WenlanError> {
        let _space_write_guard = self.space_write_lock.lock().await;
        // memories.space is NOT NULL since migration 91 — unfiled folds to the
        // reserved UNFILED_SPACE_ID sentinel rather than SQL NULL.
        let space = Some(space.unwrap_or(UNFILED_SPACE_ID));
        self.apply_memory_update(source_id, None, Some(space), false, None, None)
            .await
    }

