    pub async fn get_memory_stats(&self) -> Result<MemoryStats, WenlanError> {
        let conn = self.conn.lock().await;

        // Total distinct memories
        let mut total_rows = conn
            .query(
                "SELECT COUNT(DISTINCT source_id) FROM memories WHERE source = 'memory'",
                libsql::params![],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("memory_stats total: {}", e)))?;
        let total = if let Some(row) = total_rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            row.get::<u64>(0).unwrap_or(0)
        } else {
            0
        };

        // New today (last 24h)
        let since = chrono::Utc::now().timestamp() - 86400;
        let mut new_rows = conn
            .query(
                "SELECT COUNT(DISTINCT source_id) FROM memories WHERE source = 'memory' AND last_modified > ?1",
                libsql::params![since],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("memory_stats new: {}", e)))?;
        let new_today = if let Some(row) = new_rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            row.get::<u64>(0).unwrap_or(0)
        } else {
            0
        };

        // Confirmed count
        let mut conf_rows = conn
            .query(
                "SELECT COUNT(DISTINCT source_id) FROM memories WHERE source = 'memory' AND confirmed = 1",
                libsql::params![],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("memory_stats confirmed: {}", e)))?;
        let confirmed = if let Some(row) = conf_rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            row.get::<u64>(0).unwrap_or(0)
        } else {
            0
        };

        // Space breakdown
        let mut domain_rows = conn
            .query(
                "SELECT COALESCE(space, 'uncategorized') as d, COUNT(DISTINCT source_id) as c
                 FROM memories WHERE source = 'memory'
                 GROUP BY d ORDER BY c DESC",
                libsql::params![],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("memory_stats domains: {}", e)))?;

        let mut domains = Vec::new();
        while let Some(row) = domain_rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            domains.push(DomainInfo {
                name: row.get::<String>(0).unwrap_or_default(),
                count: row.get::<u64>(1).unwrap_or(0),
            });
        }

        // Type breakdown
        let mut type_rows = conn
            .query(
                "SELECT COALESCE(memory_type, 'unknown') as mt, COUNT(DISTINCT source_id) as c
                 FROM memories WHERE source = 'memory'
                 GROUP BY mt ORDER BY c DESC",
                libsql::params![],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("memory_stats types: {}", e)))?;

        let mut by_type = Vec::new();
        while let Some(row) = type_rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            by_type.push(TypeBreakdown {
                memory_type: row.get::<String>(0).unwrap_or_default(),
                count: row.get::<u64>(1).unwrap_or(0),
            });
        }

        // Entity-linked count
        let mut el_rows = conn
            .query(
                "SELECT COUNT(DISTINCT source_id) FROM memories WHERE source = 'memory' AND entity_id IS NOT NULL",
                libsql::params![],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("memory_stats entity_linked: {}", e)))?;
        let entity_linked = if let Some(row) = el_rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            row.get::<u64>(0).unwrap_or(0)
        } else {
            0
        };

        // Enrichment pending count
        let mut ep_rows = conn
            .query(
                "SELECT COUNT(DISTINCT source_id) FROM memories WHERE source = 'memory' AND source_id NOT IN (SELECT DISTINCT source_id FROM enrichment_steps)",
                libsql::params![],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("memory_stats enrichment: {}", e)))?;
        let enrichment_pending = if let Some(row) = ep_rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            row.get::<u64>(0).unwrap_or(0)
        } else {
            0
        };

        Ok(MemoryStats {
            total,
            new_today,
            confirmed,
            domains,
            by_type,
            entity_linked,
            enrichment_pending,
        })
    }

    /// Aggregate impact metrics for the homepage dashboard.
    /// Combines access_log (today/week granularity) with access_count (all-time).
    pub async fn get_home_stats(&self) -> Result<HomeStats, WenlanError> {
        let conn = self.conn.lock().await;
        let now = chrono::Utc::now().timestamp();
        let today_start = now - 86400;
        let week_start = now - 7 * 86400;

        // ---- Reuse same queries as get_memory_stats for total/new_today/confirmed ----

        let mut rows = conn
            .query(
                "SELECT COUNT(DISTINCT source_id) FROM memories WHERE source = 'memory'",
                libsql::params![],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("home_stats total: {e}")))?;
        let total = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
            .map(|r| r.get::<u64>(0).unwrap_or(0))
            .unwrap_or(0);

        let mut rows = conn
            .query(
                "SELECT COUNT(DISTINCT source_id) FROM memories WHERE source = 'memory' AND last_modified > ?1 AND source_id NOT LIKE 'merged_%'",
                libsql::params![today_start],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("home_stats new_today: {e}")))?;
        let new_today = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
            .map(|r| r.get::<u64>(0).unwrap_or(0))
            .unwrap_or(0);

        let mut rows = conn
            .query(
                "SELECT COUNT(DISTINCT source_id) FROM memories WHERE source = 'memory' AND confirmed = 1",
                libsql::params![],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("home_stats confirmed: {e}")))?;
        let confirmed = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
            .map(|r| r.get::<u64>(0).unwrap_or(0))
            .unwrap_or(0);

        // ---- Distillation stats ----

        let mut ingested_rows = conn
            .query(
                "SELECT COUNT(DISTINCT source_id) FROM memories WHERE source = 'memory'",
                (),
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("distillation ingested: {}", e)))?;
        let total_ingested = ingested_rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
            .map(|r| r.get::<u64>(0).unwrap_or(0))
            .unwrap_or(0);

        // Count memories actually superseded by another memory (distilled away)
        let mut superseded_rows = conn
            .query(
                "SELECT COUNT(DISTINCT c.source_id) FROM memories c \
                 INNER JOIN memories s ON s.supersedes = c.source_id AND s.source = 'memory' \
                 WHERE c.source = 'memory'",
                (),
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("distillation superseded: {}", e)))?;
        let superseded_count = superseded_rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
            .map(|r| r.get::<u64>(0).unwrap_or(0))
            .unwrap_or(0);
        let active_insights = total_ingested.saturating_sub(superseded_count);

        // Count distilled memories created today (merged_* source_ids created in last 24h)
        let mut distilled_today_rows = conn
            .query(
                "SELECT COUNT(DISTINCT source_id) FROM memories \
                 WHERE source = 'memory' AND source_id LIKE 'merged_%' AND supersede_mode <> 'archive' AND last_modified > ?1",
                libsql::params![today_start],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("distilled_today: {}", e)))?;
        let distilled_today = distilled_today_rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
            .map(|r| r.get::<u64>(0).unwrap_or(0))
            .unwrap_or(0);

        // Count all distilled memories (merged_* all time)
        let mut distilled_all_rows = conn
            .query(
                "SELECT COUNT(DISTINCT source_id) FROM memories \
                 WHERE source = 'memory' AND source_id LIKE 'merged_%' AND supersede_mode <> 'archive'",
                (),
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("distilled_all: {}", e)))?;
        let distilled_all = distilled_all_rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
            .map(|r| r.get::<u64>(0).unwrap_or(0))
            .unwrap_or(0);

        // Count source memories consumed by distillation:
        // memories referenced by a merged_* memory's supersedes chain + other sources archived during apply_merge.
        // Use: count archived non-merged, non-decision memories (decisions use archive for history, not distillation).
        let mut archived_rows = conn
            .query(
                "SELECT COUNT(DISTINCT source_id) FROM memories \
                 WHERE source = 'memory' AND supersede_mode = 'archive' \
                   AND source_id NOT LIKE 'merged_%' AND source_id NOT LIKE 'recap_%' \
                   AND memory_type <> 'decision'",
                (),
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("sources_archived: {}", e)))?;
        let sources_archived = archived_rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
            .map(|r| r.get::<u64>(0).unwrap_or(0))
            .unwrap_or(0);

        // ---- Times served today (from access_log, memory sources only) ----

        let mut rows = conn
            .query(
                "SELECT COUNT(*) FROM access_log a \
                 JOIN memories c ON c.source_id = a.source_id AND c.chunk_index = 0 \
                 WHERE a.accessed_at > ?1 AND c.source = 'memory'",
                libsql::params![today_start],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("home_stats served_today: {e}")))?;
        let times_served_today = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
            .map(|r| r.get::<u64>(0).unwrap_or(0))
            .unwrap_or(0);

        // ---- Words saved today (memory sources only) ----

        let mut rows = conn
            .query(
                "SELECT COALESCE(SUM(c.word_count), 0) FROM access_log a \
                 JOIN memories c ON c.source_id = a.source_id AND c.chunk_index = 0 \
                 WHERE a.accessed_at > ?1 AND c.source = 'memory'",
                libsql::params![today_start],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("home_stats words_today: {e}")))?;
        let words_saved_today = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
            .map(|r| r.get::<u64>(0).unwrap_or(0))
            .unwrap_or(0);

        // ---- Times served this week (from access_log, memory sources only) ----

        let mut rows = conn
            .query(
                "SELECT COUNT(*) FROM access_log a \
                 JOIN memories c ON c.source_id = a.source_id AND c.chunk_index = 0 \
                 WHERE a.accessed_at > ?1 AND c.source = 'memory'",
                libsql::params![week_start],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("home_stats served_week: {e}")))?;
        let times_served_week = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
            .map(|r| r.get::<u64>(0).unwrap_or(0))
            .unwrap_or(0);

        // ---- Words saved this week (memory sources only) ----

        let mut rows = conn
            .query(
                "SELECT COALESCE(SUM(c.word_count), 0) FROM access_log a \
                 JOIN memories c ON c.source_id = a.source_id AND c.chunk_index = 0 \
                 WHERE a.accessed_at > ?1 AND c.source = 'memory'",
                libsql::params![week_start],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("home_stats words_week: {e}")))?;
        let words_saved_week = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
            .map(|r| r.get::<u64>(0).unwrap_or(0))
            .unwrap_or(0);

        // ---- Times served all-time (from access_log, consistent with today/week) ----

        let mut rows = conn
            .query(
                "SELECT COUNT(*) FROM access_log a \
                 JOIN memories c ON c.source_id = a.source_id AND c.chunk_index = 0 \
                 WHERE c.source = 'memory'",
                libsql::params![],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("home_stats served_all: {e}")))?;
        let times_served_all = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
            .map(|r| r.get::<u64>(0).unwrap_or(0))
            .unwrap_or(0);

        // ---- Words saved all-time (from access_log, consistent with today/week) ----

        let mut rows = conn
            .query(
                "SELECT COALESCE(SUM(c.word_count), 0) FROM access_log a \
                 JOIN memories c ON c.source_id = a.source_id AND c.chunk_index = 0 \
                 WHERE c.source = 'memory'",
                libsql::params![],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("home_stats words_all: {e}")))?;
        let words_saved_all = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
            .map(|r| r.get::<u64>(0).unwrap_or(0))
            .unwrap_or(0);

        // ---- Key insights (all classified memory types) ----

        // 'goal' dropped per Phase 0 — migration 45 folded all goal rows into
        // identity, and MemoryType::Goal was removed from wenlan-types. Any
        // residual goal-typed rows would have been migrated; keeping 'goal' in
        // the IN clause is dead.
        let mut rows = conn
            .query(
                "SELECT COUNT(DISTINCT source_id) FROM memories \
                 WHERE source = 'memory' AND confirmed = 1 \
                   AND memory_type IN ('identity', 'preference', 'decision', 'lesson', 'gotcha', 'fact')",
                libsql::params![],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("home_stats insights: {e}")))?;
        let corrections_active = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
            .map(|r| r.get::<u64>(0).unwrap_or(0))
            .unwrap_or(0);

        // ---- Top 3 memories this week (from access_log) ----

        let mut top_rows = conn
            .query(
                "SELECT a.source_id, SUBSTR(c.content, 1, 200), c.memory_type, c.space, COUNT(*) as cnt \
                 FROM access_log a \
                 JOIN memories c ON c.source_id = a.source_id AND c.chunk_index = 0 \
                 WHERE a.accessed_at > ?1 \
                 GROUP BY a.source_id ORDER BY cnt DESC LIMIT 3",
                libsql::params![week_start],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("home_stats top_week: {e}")))?;

        let mut top_memories = Vec::new();
        while let Some(row) = top_rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            top_memories.push(TopMemory {
                source_id: row.get::<String>(0).unwrap_or_default(),
                content: row.get::<String>(1).unwrap_or_default(),
                memory_type: match row.get_value(2) {
                    Ok(libsql::Value::Text(s)) => Some(s),
                    _ => None,
                },
                space: match row.get_value(3) {
                    Ok(libsql::Value::Text(s)) => Some(s),
                    _ => None,
                },
                times_retrieved: row.get::<u64>(4).unwrap_or(0),
            });
        }

        // ---- Fallback: top 3 all-time if no weekly data ----

        if top_memories.is_empty() {
            let mut fallback_rows = conn
                .query(
                    "SELECT source_id, SUBSTR(content, 1, 200), memory_type, space, access_count \
                     FROM memories WHERE source = 'memory' AND access_count > 0 AND chunk_index = 0 \
                     ORDER BY access_count DESC LIMIT 3",
                    libsql::params![],
                )
                .await
                .map_err(|e| WenlanError::VectorDb(format!("home_stats top_alltime: {e}")))?;

            while let Some(row) = fallback_rows
                .next()
                .await
                .map_err(|e| WenlanError::VectorDb(e.to_string()))?
            {
                top_memories.push(TopMemory {
                    source_id: row.get::<String>(0).unwrap_or_default(),
                    content: row.get::<String>(1).unwrap_or_default(),
                    memory_type: match row.get_value(2) {
                        Ok(libsql::Value::Text(s)) => Some(s),
                        _ => None,
                    },
                    space: match row.get_value(3) {
                        Ok(libsql::Value::Text(s)) => Some(s),
                        _ => None,
                    },
                    times_retrieved: row.get::<u64>(4).unwrap_or(0),
                });
            }
        }

        Ok(HomeStats {
            total,
            new_today,
            confirmed,
            total_ingested,
            active_insights,
            distilled_today,
            distilled_all,
            sources_archived,
            times_served_today,
            words_saved_today,
            times_served_week,
            words_saved_week,
            times_served_all,
            words_saved_all,
            corrections_active,
            top_memories,
        })
    }

    pub async fn get_home_stats_scoped(&self, scope: &ReadScope) -> Result<HomeStats, WenlanError> {
        if matches!(scope, ReadScope::Global) {
            return self.get_home_stats().await;
        }

        let now = chrono::Utc::now().timestamp();
        let today_start = now - 86400;
        let week_start = now - 7 * 86400;
        let mut conditions = vec!["source = 'memory'".to_string()];
        let mut values = Vec::new();
        push_read_scope_filter_folded(scope, "space", &mut conditions, &mut values);
        values.extend([
            libsql::Value::Integer(today_start),
            libsql::Value::Integer(today_start),
            libsql::Value::Integer(today_start),
            libsql::Value::Integer(today_start),
            libsql::Value::Integer(week_start),
            libsql::Value::Integer(week_start),
        ]);
        let sql = format!(
            "WITH scoped AS (
                 SELECT source_id, last_modified, confirmed, supersedes, supersede_mode,
                        memory_type, chunk_index, word_count, content, space, access_count
                   FROM memories WHERE {}
             )
             SELECT
                 (SELECT COUNT(DISTINCT source_id) FROM scoped),
                 (SELECT COUNT(DISTINCT source_id) FROM scoped
                   WHERE last_modified > ? AND source_id NOT LIKE 'merged_%'),
                 (SELECT COUNT(DISTINCT source_id) FROM scoped WHERE confirmed = 1),
                 (SELECT COUNT(DISTINCT source_id) FROM scoped),
                 (SELECT COUNT(DISTINCT c.source_id) FROM scoped c
                    INNER JOIN scoped s ON s.supersedes = c.source_id),
                 (SELECT COUNT(DISTINCT source_id) FROM scoped
                   WHERE source_id LIKE 'merged_%' AND supersede_mode <> 'archive'
                     AND last_modified > ?),
                 (SELECT COUNT(DISTINCT source_id) FROM scoped
                   WHERE source_id LIKE 'merged_%' AND supersede_mode <> 'archive'),
                 (SELECT COUNT(DISTINCT source_id) FROM scoped
                   WHERE supersede_mode = 'archive'
                     AND source_id NOT LIKE 'merged_%' AND source_id NOT LIKE 'recap_%'
                     AND memory_type <> 'decision'),
                 (SELECT COUNT(*) FROM access_log a
                    JOIN scoped c ON c.source_id = a.source_id AND c.chunk_index = 0
                   WHERE a.accessed_at > ?),
                 (SELECT COALESCE(SUM(c.word_count), 0) FROM access_log a
                    JOIN scoped c ON c.source_id = a.source_id AND c.chunk_index = 0
                   WHERE a.accessed_at > ?),
                 (SELECT COUNT(*) FROM access_log a
                    JOIN scoped c ON c.source_id = a.source_id AND c.chunk_index = 0
                   WHERE a.accessed_at > ?),
                 (SELECT COALESCE(SUM(c.word_count), 0) FROM access_log a
                    JOIN scoped c ON c.source_id = a.source_id AND c.chunk_index = 0
                   WHERE a.accessed_at > ?),
                 (SELECT COUNT(*) FROM access_log a
                    JOIN scoped c ON c.source_id = a.source_id AND c.chunk_index = 0),
                 (SELECT COALESCE(SUM(c.word_count), 0) FROM access_log a
                    JOIN scoped c ON c.source_id = a.source_id AND c.chunk_index = 0),
                 (SELECT COUNT(DISTINCT source_id) FROM scoped
                   WHERE confirmed = 1
                     AND memory_type IN ('identity', 'preference', 'decision', 'lesson', 'gotcha', 'fact'))",
            conditions.join(" AND ")
        );

        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(&sql, libsql::params_from_iter(values))
            .await
            .map_err(|e| WenlanError::VectorDb(format!("home_stats scoped: {e}")))?;
        let row = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(format!("home_stats scoped row: {e}")))?
            .ok_or_else(|| WenlanError::VectorDb("home_stats scoped row missing".to_string()))?;
        let total = row.get::<u64>(0).unwrap_or(0);
        let new_today = row.get::<u64>(1).unwrap_or(0);
        let confirmed = row.get::<u64>(2).unwrap_or(0);
        let total_ingested = row.get::<u64>(3).unwrap_or(0);
        let superseded_count = row.get::<u64>(4).unwrap_or(0);
        let distilled_today = row.get::<u64>(5).unwrap_or(0);
        let distilled_all = row.get::<u64>(6).unwrap_or(0);
        let sources_archived = row.get::<u64>(7).unwrap_or(0);
        let times_served_today = row.get::<u64>(8).unwrap_or(0);
        let words_saved_today = row.get::<u64>(9).unwrap_or(0);
        let times_served_week = row.get::<u64>(10).unwrap_or(0);
        let words_saved_week = row.get::<u64>(11).unwrap_or(0);
        let times_served_all = row.get::<u64>(12).unwrap_or(0);
        let words_saved_all = row.get::<u64>(13).unwrap_or(0);
        let corrections_active = row.get::<u64>(14).unwrap_or(0);
        drop(rows);

        let mut top_conditions = vec!["source = 'memory'".to_string()];
        let mut top_values = Vec::new();
        push_read_scope_filter_folded(scope, "space", &mut top_conditions, &mut top_values);
        top_values.push(libsql::Value::Integer(week_start));
        let top_sql = format!(
            "WITH scoped AS (
                 SELECT source_id, chunk_index, content, memory_type, space
                   FROM memories WHERE {}
             )
             SELECT a.source_id, SUBSTR(c.content, 1, 200), c.memory_type, c.space,
                    COUNT(*) AS cnt
               FROM access_log a
               JOIN scoped c ON c.source_id = a.source_id AND c.chunk_index = 0
              WHERE a.accessed_at > ?
              GROUP BY a.source_id
              ORDER BY cnt DESC
              LIMIT 3",
            top_conditions.join(" AND ")
        );
        let mut top_rows = conn
            .query(&top_sql, libsql::params_from_iter(top_values))
            .await
            .map_err(|e| WenlanError::VectorDb(format!("home_stats scoped top_week: {e}")))?;
        let mut top_memories = Vec::new();
        while let Some(row) = top_rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(format!("home_stats scoped top row: {e}")))?
        {
            top_memories.push(TopMemory {
                source_id: row.get::<String>(0).unwrap_or_default(),
                content: row.get::<String>(1).unwrap_or_default(),
                memory_type: row.get::<Option<String>>(2).unwrap_or(None),
                space: row.get::<Option<String>>(3).unwrap_or(None),
                times_retrieved: row.get::<u64>(4).unwrap_or(0),
            });
        }
        drop(top_rows);

        if top_memories.is_empty() {
            let mut fallback_conditions = vec![
                "source = 'memory'".to_string(),
                "access_count > 0".to_string(),
                "chunk_index = 0".to_string(),
            ];
            let mut fallback_values = Vec::new();
            push_read_scope_filter_folded(
                scope,
                "space",
                &mut fallback_conditions,
                &mut fallback_values,
            );
            let fallback_sql = format!(
                "SELECT source_id, SUBSTR(content, 1, 200), memory_type, space, access_count
                   FROM memories
                  WHERE {}
                  ORDER BY access_count DESC
                  LIMIT 3",
                fallback_conditions.join(" AND ")
            );
            let mut fallback_rows = conn
                .query(&fallback_sql, libsql::params_from_iter(fallback_values))
                .await
                .map_err(|e| {
                    WenlanError::VectorDb(format!("home_stats scoped top_alltime: {e}"))
                })?;
            while let Some(row) = fallback_rows.next().await.map_err(|e| {
                WenlanError::VectorDb(format!("home_stats scoped fallback row: {e}"))
            })? {
                top_memories.push(TopMemory {
                    source_id: row.get::<String>(0).unwrap_or_default(),
                    content: row.get::<String>(1).unwrap_or_default(),
                    memory_type: row.get::<Option<String>>(2).unwrap_or(None),
                    space: row.get::<Option<String>>(3).unwrap_or(None),
                    times_retrieved: row.get::<u64>(4).unwrap_or(0),
                });
            }
        }

        Ok(HomeStats {
            total,
            new_today,
            confirmed,
            total_ingested,
            active_insights: total_ingested.saturating_sub(superseded_count),
            distilled_today,
            distilled_all,
            sources_archived,
            times_served_today,
            words_saved_today,
            times_served_week,
            words_saved_week,
            times_served_all,
            words_saved_all,
            corrections_active,
            top_memories,
        })
    }

    // ==================== Version Chain ====================

    /// Walk the version chain for a memory, returning all versions ordered oldest->newest.
    pub async fn get_version_chain(
        &self,
        source_id: &str,
    ) -> Result<Vec<MemoryVersionItem>, WenlanError> {
        let conn = self.conn.lock().await;

        // Step 1: Walk backward to find root
        let mut current = source_id.to_string();
        let mut visited = std::collections::HashSet::new();
        loop {
            if !visited.insert(current.clone()) {
                break; // cycle detection
            }

            // Get the supersedes field for current source_id
            let mut rows = conn
                .query(
                    "SELECT supersedes FROM memories WHERE source_id = ?1 AND source = 'memory' LIMIT 1",
                    libsql::params![current.clone()],
                )
                .await
                .map_err(|e| WenlanError::VectorDb(format!("version_chain backward: {e}")))?;

            if let Some(row) = rows
                .next()
                .await
                .map_err(|e| WenlanError::VectorDb(format!("version_chain row: {e}")))?
            {
                // supersedes may be NULL — get_value lets us check
                match row.get_value(0) {
                    Ok(libsql::Value::Text(prev)) if !prev.is_empty() => {
                        current = prev;
                        continue;
                    }
                    _ => break,
                }
            } else {
                break; // source_id not found
            }
        }

        let root = current;

        // Step 2: Walk forward from root
        let mut chain = Vec::new();
        let mut current = root;
        let mut visited = std::collections::HashSet::new();
        loop {
            if !visited.insert(current.clone()) {
                break; // cycle detection
            }

            // Load this version's data (aggregate across rows)
            let mut rows = conn
                .query(
                    "SELECT source_id, MAX(title), MAX(content), MAX(memory_type),
                            MAX(CAST(confirmed AS INTEGER)), MAX(supersedes), MAX(last_modified)
                     FROM memories WHERE source_id = ?1 AND source = 'memory' GROUP BY source_id",
                    libsql::params![current.clone()],
                )
                .await
                .map_err(|e| WenlanError::VectorDb(format!("version_chain forward: {e}")))?;

            if let Some(row) = rows
                .next()
                .await
                .map_err(|e| WenlanError::VectorDb(format!("version_chain row: {e}")))?
            {
                chain.push(MemoryVersionItem {
                    source_id: row.get::<String>(0).unwrap_or_default(),
                    title: row.get::<String>(1).unwrap_or_default(),
                    content: row.get::<String>(2).unwrap_or_default(),
                    memory_type: row.get::<Option<String>>(3).unwrap_or(None),
                    confirmed: row.get::<i64>(4).unwrap_or(0) != 0,
                    supersedes: row.get::<Option<String>>(5).unwrap_or(None),
                    last_modified: row.get::<i64>(6).unwrap_or(0),
                });
            } else {
                break; // source_id not found in DB
            }

            // Find the next version (who supersedes current?)
            let mut next_rows = conn
                .query(
                    "SELECT source_id FROM memories WHERE supersedes = ?1 AND source = 'memory' GROUP BY source_id LIMIT 1",
                    libsql::params![current.clone()],
                )
                .await
                .map_err(|e| WenlanError::VectorDb(format!("version_chain next: {e}")))?;

            if let Some(row) = next_rows
                .next()
                .await
                .map_err(|e| WenlanError::VectorDb(format!("version_chain next row: {e}")))?
            {
                current = row.get::<String>(0).unwrap_or_default();
            } else {
                break; // end of chain
            }
        }

        Ok(chain)
    }

    pub async fn get_version_chain_scoped(
        &self,
        source_id: &str,
        scope: &ReadScope,
    ) -> Result<Option<Vec<MemoryVersionItem>>, WenlanError> {
        let (scope_sql, scope_value) = match scope {
            ReadScope::Global => ("", None),
            ReadScope::Space(space) => ("AND space = ?2", Some(libsql::Value::Text(space.clone()))),
            ReadScope::Uncategorized => (
                "AND (space IS NULL OR space = '00000000-0000-4000-8000-000000000001')",
                None,
            ),
        };
        let conn = self.conn.lock().await;

        let mut current = source_id.to_string();
        let mut root = current.clone();
        let mut found_start = false;
        let mut visited = std::collections::HashSet::new();
        loop {
            if !visited.insert(current.clone()) {
                break;
            }
            let sql = format!(
                "SELECT supersedes FROM memories
                 WHERE source_id = ?1 AND source = 'memory' AND chunk_index = 0 {scope_sql}
                 LIMIT 1"
            );
            let params = match &scope_value {
                Some(value) => vec![libsql::Value::Text(current.clone()), value.clone()],
                None => vec![libsql::Value::Text(current.clone())],
            };
            let predecessor = {
                let mut rows = conn.query(&sql, params).await.map_err(|e| {
                    WenlanError::VectorDb(format!("version_chain_scoped backward: {e}"))
                })?;
                rows.next()
                    .await
                    .map_err(|e| WenlanError::VectorDb(format!("version_chain_scoped row: {e}")))?
                    .map(|row| row.get::<Option<String>>(0).unwrap_or(None))
            };
            let Some(predecessor) = predecessor else {
                if !found_start {
                    return Ok(None);
                }
                break;
            };
            found_start = true;
            root = current.clone();
            match predecessor.filter(|value| !value.is_empty()) {
                Some(previous) => current = previous,
                None => break,
            }
        }

        let mut chain = Vec::new();
        let mut current = root;
        let mut visited = std::collections::HashSet::new();
        loop {
            if !visited.insert(current.clone()) {
                break;
            }
            let item_sql = format!(
                "SELECT source_id, MAX(title), MAX(content), MAX(memory_type),
                        MAX(CAST(confirmed AS INTEGER)), MAX(supersedes), MAX(last_modified)
                 FROM memories
                 WHERE source_id = ?1 AND source = 'memory' {scope_sql}
                 GROUP BY source_id"
            );
            let params = match &scope_value {
                Some(value) => vec![libsql::Value::Text(current.clone()), value.clone()],
                None => vec![libsql::Value::Text(current.clone())],
            };
            let item = {
                let mut rows = conn.query(&item_sql, params).await.map_err(|e| {
                    WenlanError::VectorDb(format!("version_chain_scoped forward: {e}"))
                })?;
                rows.next()
                    .await
                    .map_err(|e| WenlanError::VectorDb(format!("version_chain_scoped row: {e}")))?
                    .map(|row| MemoryVersionItem {
                        source_id: row.get::<String>(0).unwrap_or_default(),
                        title: row.get::<String>(1).unwrap_or_default(),
                        content: row.get::<String>(2).unwrap_or_default(),
                        memory_type: row.get::<Option<String>>(3).unwrap_or(None),
                        confirmed: row.get::<i64>(4).unwrap_or(0) != 0,
                        supersedes: row.get::<Option<String>>(5).unwrap_or(None),
                        last_modified: row.get::<i64>(6).unwrap_or(0),
                    })
            };
            let Some(mut item) = item else {
                break;
            };
            if let Some(predecessor) = item.supersedes.clone() {
                let predecessor_sql = format!(
                    "SELECT 1 FROM memories
                     WHERE source_id = ?1 AND source = 'memory' AND chunk_index = 0 {scope_sql}
                     LIMIT 1"
                );
                let params = match &scope_value {
                    Some(value) => {
                        vec![libsql::Value::Text(predecessor), value.clone()]
                    }
                    None => vec![libsql::Value::Text(predecessor)],
                };
                let mut rows = conn.query(&predecessor_sql, params).await.map_err(|e| {
                    WenlanError::VectorDb(format!("version_chain_scoped predecessor: {e}"))
                })?;
                if rows
                    .next()
                    .await
                    .map_err(|e| {
                        WenlanError::VectorDb(format!("version_chain_scoped predecessor row: {e}"))
                    })?
                    .is_none()
                {
                    item.supersedes = None;
                }
            }
            chain.push(item);

            let next_sql = format!(
                "SELECT source_id FROM memories
                 WHERE supersedes = ?1 AND source = 'memory' AND chunk_index = 0 {scope_sql}
                 GROUP BY source_id LIMIT 1"
            );
            let params = match &scope_value {
                Some(value) => vec![libsql::Value::Text(current.clone()), value.clone()],
                None => vec![libsql::Value::Text(current.clone())],
            };
            let next = {
                let mut rows = conn.query(&next_sql, params).await.map_err(|e| {
                    WenlanError::VectorDb(format!("version_chain_scoped next: {e}"))
                })?;
                rows.next()
                    .await
                    .map_err(|e| {
                        WenlanError::VectorDb(format!("version_chain_scoped next row: {e}"))
                    })?
                    .map(|row| row.get::<String>(0).unwrap_or_default())
            };
            match next.filter(|value| !value.is_empty()) {
                Some(next) => current = next,
                None => break,
            }
        }

        Ok(Some(chain))
    }

    // ==================== Profile CRUD ====================

    pub async fn bootstrap_profile(&self) -> Result<(), WenlanError> {
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query("SELECT COUNT(*) FROM profiles", ())
            .await
            .map_err(|e| WenlanError::VectorDb(format!("bootstrap_profile count: {}", e)))?;
        let count: i64 = if let Some(row) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            row.get::<i64>(0).unwrap_or(0)
        } else {
            0
        };
        if count == 0 {
            let id = uuid::Uuid::new_v4().to_string();
            let now = chrono::Utc::now().timestamp();
            conn.execute(
                "INSERT INTO profiles (id, name, display_name, created_at, updated_at) VALUES (?1, ?2, NULL, ?3, ?3)",
                libsql::params![id, "User".to_string(), now],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("bootstrap_profile insert: {}", e)))?;
        }
        Ok(())
    }

    pub async fn get_profile(&self) -> Result<Option<Profile>, WenlanError> {
        self.bootstrap_profile().await?;
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query("SELECT id, name, display_name, email, bio, avatar_path, created_at, updated_at FROM profiles LIMIT 1", ())
            .await
            .map_err(|e| WenlanError::VectorDb(format!("get_profile: {}", e)))?;
        if let Some(row) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            Ok(Some(Profile {
                id: row.get::<String>(0).unwrap_or_default(),
                name: row.get::<String>(1).unwrap_or_default(),
                display_name: row.get::<Option<String>>(2).unwrap_or(None),
                email: row.get::<Option<String>>(3).unwrap_or(None),
                bio: row.get::<Option<String>>(4).unwrap_or(None),
                avatar_path: row.get::<Option<String>>(5).unwrap_or(None),
                created_at: row.get::<i64>(6).unwrap_or(0),
                updated_at: row.get::<i64>(7).unwrap_or(0),
            }))
        } else {
            Ok(None)
        }
    }

    pub async fn update_profile(
        &self,
        id: &str,
        name: Option<&str>,
        display_name: Option<&str>,
        email: Option<&str>,
        bio: Option<&str>,
        avatar_path: Option<&str>,
    ) -> Result<(), WenlanError> {
        let conn = self.conn.lock().await;
        let now = chrono::Utc::now().timestamp();

        let mut sets = vec!["updated_at = ?1".to_string()];
        let mut params: Vec<libsql::Value> = vec![now.into()];

        if let Some(n) = name {
            params.push(n.into());
            sets.push(format!("name = ?{}", params.len()));
        }

        // Helper: empty string → NULL, non-empty → value
        let nullable_fields: &[(&str, Option<&str>)] = &[
            ("display_name", display_name),
            ("email", email),
            ("bio", bio),
            ("avatar_path", avatar_path),
        ];
        for (col, val) in nullable_fields {
            if let Some(v) = val {
                if v.is_empty() {
                    params.push(libsql::Value::Null);
                } else {
                    params.push((*v).into());
                }
                sets.push(format!("{} = ?{}", col, params.len()));
            }
        }

        params.push(id.into());
        let sql = format!(
            "UPDATE profiles SET {} WHERE id = ?{}",
            sets.join(", "),
            params.len()
        );

        conn.execute(&sql, libsql::params_from_iter(params))
            .await
            .map_err(|e| WenlanError::VectorDb(format!("update_profile: {}", e)))?;
        Ok(())
    }

    // ==================== Agent Connection CRUD ====================

    pub async fn register_agent(&self, name: &str) -> Result<AgentConnection, WenlanError> {
        // Canonicalize on the way in so `"Claude Code"` and `"claude-code"`
        // collapse to one row. The caller's original label — if it differs —
        // is promoted to `display_name` for UI.
        let canonical = canonicalize_agent_id(name);
        let original_label = if canonical != name.trim().to_lowercase() || canonical != name {
            Some(name.to_string())
        } else {
            None
        };
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT id, name, display_name, agent_type, description, enabled, trust_level, last_seen_at, memory_count, created_at, updated_at
                 FROM agent_connections WHERE name = ?1",
                libsql::params![canonical.clone()],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("register_agent select: {}", e)))?;

        if let Some(row) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            return Ok(Self::row_to_agent(&row));
        }
        drop(rows);

        let id = uuid::Uuid::new_v4().to_string();
        let now = chrono::Utc::now().timestamp();
        let display_name_to_store = original_label
            .clone()
            .or_else(|| known_client_display_name(&canonical).map(|s| s.to_string()));
        // Default new registrations to `"full"`. Rationale: on a single-user
        // local server, registration IS the trust gesture — if you ran the
        // SetupWizard for this agent, you want it to see your identity and
        // preferences. The old default (`"review"`) silently gated Tier 1
        // chat-context for every agent, which nobody noticed or wanted.
        // Unregistered callers still fall through to `"unknown"` in
        // `handle_context` and only see Tier 3 (search results).
        conn.execute(
            "INSERT INTO agent_connections (id, name, display_name, agent_type, description, enabled, trust_level, last_seen_at, memory_count, created_at, updated_at)
             VALUES (?1, ?2, ?3, 'api', NULL, 1, 'full', NULL, 0, ?4, ?4)",
            libsql::params![id.clone(), canonical.clone(), display_name_to_store.clone(), now],
        )
        .await
        .map_err(|e| WenlanError::VectorDb(format!("register_agent insert: {}", e)))?;

        Ok(AgentConnection {
            id,
            name: canonical,
            display_name: display_name_to_store,
            agent_type: "api".to_string(),
            description: None,
            enabled: true,
            trust_level: "full".to_string(),
            last_seen_at: None,
            memory_count: 0,
            created_at: now,
            updated_at: now,
        })
    }

    pub async fn get_agent(&self, name: &str) -> Result<Option<AgentConnection>, WenlanError> {
        let canonical = canonicalize_agent_id(name);
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT id, name, display_name, agent_type, description, enabled, trust_level, last_seen_at, memory_count, created_at, updated_at
                 FROM agent_connections WHERE name = ?1",
                libsql::params![canonical],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("get_agent: {}", e)))?;
        if let Some(row) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            Ok(Some(Self::row_to_agent(&row)))
        } else {
            Ok(None)
        }
    }

    pub async fn list_agents(&self) -> Result<Vec<AgentConnection>, WenlanError> {
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT id, name, display_name, agent_type, description, enabled, trust_level, last_seen_at, memory_count, created_at, updated_at
                 FROM agent_connections ORDER BY COALESCE(last_seen_at, 0) DESC, created_at DESC",
                (),
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("list_agents: {}", e)))?;
        let mut agents = Vec::new();
        while let Some(row) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(e.to_string()))?
        {
            agents.push(Self::row_to_agent(&row));
        }
        Ok(agents)
    }

    pub async fn update_agent(
        &self,
        name: &str,
        agent_type: Option<&str>,
        description: Option<&str>,
        enabled: Option<bool>,
        trust_level: Option<&str>,
        display_name: Option<&str>,
    ) -> Result<(), WenlanError> {
        let canonical = canonicalize_agent_id(name);
        let conn = self.conn.lock().await;
        let now = chrono::Utc::now().timestamp();
        let mut sets = vec!["updated_at = ?1".to_string()];
        let mut params: Vec<libsql::Value> = vec![now.into()];
        if let Some(at) = agent_type {
            params.push(at.into());
            sets.push(format!("agent_type = ?{}", params.len()));
        }
        if let Some(d) = description {
            params.push(d.into());
            sets.push(format!("description = ?{}", params.len()));
        }
        if let Some(e) = enabled {
            params.push((e as i64).into());
            sets.push(format!("enabled = ?{}", params.len()));
        }
        if let Some(tl) = trust_level {
            params.push(tl.into());
            sets.push(format!("trust_level = ?{}", params.len()));
        }
        if let Some(dn) = display_name {
            // Allow explicit clearing via empty string.
            let val: libsql::Value = if dn.is_empty() {
                libsql::Value::Null
            } else {
                dn.into()
            };
            params.push(val);
            sets.push(format!("display_name = ?{}", params.len()));
        }
        params.push(canonical.into());
        let sql = format!(
            "UPDATE agent_connections SET {} WHERE name = ?{}",
            sets.join(", "),
            params.len()
        );
        conn.execute(&sql, libsql::params_from_iter(params))
            .await
            .map_err(|e| WenlanError::VectorDb(format!("update_agent: {}", e)))?;
        Ok(())
    }

    pub async fn delete_agent(&self, name: &str) -> Result<(), WenlanError> {
        let canonical = canonicalize_agent_id(name);
        let conn = self.conn.lock().await;
        conn.execute(
            "DELETE FROM agent_connections WHERE name = ?1",
            libsql::params![canonical],
        )
        .await
        .map_err(|e| WenlanError::VectorDb(format!("delete_agent: {}", e)))?;
        Ok(())
    }

    pub async fn touch_agent(&self, name: &str) -> Result<(), WenlanError> {
        let canonical = canonicalize_agent_id(name);
        let conn = self.conn.lock().await;
        let now = chrono::Utc::now().timestamp();
        conn.execute(
            "UPDATE agent_connections SET memory_count = memory_count + 1, last_seen_at = ?1, updated_at = ?1 WHERE name = ?2",
            libsql::params![now, canonical],
        )
        .await
        .map_err(|e| WenlanError::VectorDb(format!("touch_agent: {}", e)))?;
        Ok(())
    }

    /// Check if an agent is allowed to write. Auto-registers if unknown.
    /// Returns the agent's trust_level on success, or WenlanError::AgentDisabled if disabled.
    pub async fn check_agent_for_write(&self, agent_name: &str) -> Result<String, WenlanError> {
        let agent = self.register_agent(agent_name).await?;
        if !agent.enabled {
            return Err(WenlanError::AgentDisabled(format!(
                "Agent '{}' is disabled",
                agent_name
            )));
        }
        self.touch_agent(agent_name).await?;
        Ok(agent.trust_level)
    }

    /// Convenience wrapper for Option<&str> source_agent.
    /// Returns "full" for None (local/first-party writes).
    pub async fn check_agent_for_write_optional(
        &self,
        agent_name: Option<&str>,
    ) -> Result<String, WenlanError> {
        match agent_name {
            Some(name) => self.check_agent_for_write(name).await,
            None => Ok("full".to_string()),
        }
    }

    fn row_to_agent(row: &libsql::Row) -> AgentConnection {
        let raw_name = row.get::<String>(1).unwrap_or_default();
        // Column 2 is display_name (nullable). If the DB doesn't set one,
        // fall back to the KNOWN_CLIENTS registry so well-known technical IDs
        // (e.g. `openai-mcp`) surface with their friendly name (`ChatGPT`)
        // without requiring the user to explicitly register them.
        let display_name = row
            .get::<Option<String>>(2)
            .unwrap_or(None)
            .or_else(|| known_client_display_name(&raw_name).map(|s| s.to_string()));
        AgentConnection {
            id: row.get::<String>(0).unwrap_or_default(),
            name: raw_name,
            display_name,
            agent_type: row.get::<String>(3).unwrap_or_default(),
            description: row.get::<Option<String>>(4).unwrap_or(None),
            enabled: row.get::<i64>(5).unwrap_or(1) != 0,
            trust_level: row
                .get::<String>(6)
                .unwrap_or_else(|_| "review".to_string()),
            last_seen_at: row.get::<Option<i64>>(7).unwrap_or(None),
            memory_count: row.get::<i64>(8).unwrap_or(0),
            created_at: row.get::<i64>(9).unwrap_or(0),
            updated_at: row.get::<i64>(10).unwrap_or(0),
        }
    }

    // ==================== Onboarding Milestones ====================

    /// Record a milestone. Returns `Some(record)` if newly fired, `None` if
    /// already fired. Race-safe against concurrent callers via
    /// `ON CONFLICT ... DO NOTHING RETURNING` — two simultaneous
    /// evaluator checks cannot both fire the same milestone.
    pub async fn record_milestone(
        &self,
        id: crate::onboarding::MilestoneId,
        payload: Option<serde_json::Value>,
    ) -> Result<Option<crate::onboarding::MilestoneRecord>, WenlanError> {
        let now = chrono::Utc::now().timestamp();
        let payload_str =
            match &payload {
                Some(v) => Some(serde_json::to_string(v).map_err(|e| {
                    WenlanError::Generic(format!("record_milestone payload: {}", e))
                })?),
                None => None,
            };
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "INSERT INTO onboarding_milestones (id, first_triggered_at, payload) \
                 VALUES (?1, ?2, ?3) \
                 ON CONFLICT(id) DO NOTHING \
                 RETURNING id, first_triggered_at, acknowledged_at, payload",
                libsql::params![id.as_str(), now, payload_str],
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("record_milestone insert: {}", e)))?;
        match rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(format!("record_milestone next: {}", e)))?
        {
            Some(row) => {
                let id_str: String = row.get(0).map_err(|e| {
                    WenlanError::VectorDb(format!("record_milestone row.id: {}", e))
                })?;
                let parsed_id = crate::onboarding::MilestoneId::from_str(&id_str)
                    .map_err(WenlanError::Generic)?;
                let first_triggered_at: i64 = row.get(1).map_err(|e| {
                    WenlanError::VectorDb(format!("record_milestone row.first_triggered_at: {}", e))
                })?;
                let acknowledged_at: Option<i64> = row.get(2).map_err(|e| {
                    WenlanError::VectorDb(format!("record_milestone row.acknowledged_at: {}", e))
                })?;
                let payload_str_out: Option<String> = row.get(3).map_err(|e| {
                    WenlanError::VectorDb(format!("record_milestone row.payload: {}", e))
                })?;
                let payload_val = payload_str_out.and_then(|s| serde_json::from_str(&s).ok());
                Ok(Some(crate::onboarding::MilestoneRecord {
                    id: parsed_id,
                    first_triggered_at,
                    acknowledged_at,
                    payload: payload_val,
                }))
            }
            None => Ok(None),
        }
    }

    /// Return all milestone rows ordered by trigger time ascending. Called
    /// by the `/api/onboarding/milestones` endpoint and the cold-start
    /// toast replay logic in `MilestoneToaster`.
    pub async fn list_milestones(
        &self,
    ) -> Result<Vec<crate::onboarding::MilestoneRecord>, WenlanError> {
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT id, first_triggered_at, acknowledged_at, payload \
                 FROM onboarding_milestones ORDER BY first_triggered_at ASC",
                (),
            )
            .await
            .map_err(|e| WenlanError::VectorDb(format!("list_milestones: {}", e)))?;
        let mut out = Vec::new();
        while let Some(row) = rows
            .next()
            .await
            .map_err(|e| WenlanError::VectorDb(format!("list_milestones next: {}", e)))?
        {
            let id_str: String = row
                .get(0)
                .map_err(|e| WenlanError::VectorDb(format!("list_milestones row.id: {}", e)))?;
            let parsed_id = match crate::onboarding::MilestoneId::from_str(&id_str) {
                Ok(id) => id,
                Err(e) => {
                    log::warn!(
                        "list_milestones: skipping unknown milestone id '{}': {}",
                        id_str,
                        e
                    );
                    continue;
                }
            };
            let first_triggered_at: i64 = row.get(1).map_err(|e| {
                WenlanError::VectorDb(format!("list_milestones row.first_triggered_at: {}", e))
            })?;
            let acknowledged_at: Option<i64> = row.get(2).map_err(|e| {
                WenlanError::VectorDb(format!("list_milestones row.acknowledged_at: {}", e))
            })?;
            let payload_str: Option<String> = row.get(3).map_err(|e| {
                WenlanError::VectorDb(format!("list_milestones row.payload: {}", e))
            })?;
            let payload_val = payload_str.and_then(|s| serde_json::from_str(&s).ok());
            out.push(crate::onboarding::MilestoneRecord {
                id: parsed_id,
                first_triggered_at,
                acknowledged_at,
                payload: payload_val,
            });
        }
        Ok(out)
    }

    /// Set `acknowledged_at = now()` for the given milestone, but only if
    /// it has not already been acknowledged (so we don't overwrite the
    /// original ack timestamp on repeated clicks).
    pub async fn acknowledge_milestone(
        &self,
        id: crate::onboarding::MilestoneId,
    ) -> Result<(), WenlanError> {
        let now = chrono::Utc::now().timestamp();
        let conn = self.conn.lock().await;
        conn.execute(
            "UPDATE onboarding_milestones SET acknowledged_at = ?1 \
             WHERE id = ?2 AND acknowledged_at IS NULL",
            libsql::params![now, id.as_str()],
        )
        .await
        .map_err(|e| WenlanError::VectorDb(format!("acknowledge_milestone: {}", e)))?;
        Ok(())
    }

    /// Update the `payload.shown_count` counter for a milestone. Used by
    /// `FirstConceptModal` to track non-acknowledging dismissals so the
    /// modal self-retires after 3 shows (see spec §3.2). Returns the new
    /// count. If the milestone is not yet recorded, this is a no-op and
    /// returns 0.
    pub async fn increment_milestone_shown_count(
        &self,
        id: crate::onboarding::MilestoneId,
    ) -> Result<u32, WenlanError> {
        let conn = self.conn.lock().await;
        let mut rows = conn
            .query(
                "SELECT payload FROM onboarding_milestones WHERE id = ?1",
                libsql::params![id.as_str()],
            )
            .await
            .map_err(|e| {
                WenlanError::VectorDb(format!("increment_milestone_shown_count select: {}", e))
            })?;
        let current: Option<String> = match rows.next().await.map_err(|e| {
            WenlanError::VectorDb(format!("increment_milestone_shown_count next: {}", e))
        })? {
            Some(r) => r.get(0).map_err(|e| {
                WenlanError::VectorDb(format!("increment_milestone_shown_count row: {}", e))
            })?,
            None => return Ok(0),
        };
        let mut payload_val: serde_json::Value = current
            .as_deref()
            .and_then(|s| serde_json::from_str(s).ok())
            .unwrap_or_else(|| serde_json::json!({}));
        let count = payload_val
            .get("shown_count")
            .and_then(|v| v.as_u64())
            .unwrap_or(0) as u32
            + 1;
        payload_val["shown_count"] = serde_json::json!(count);
        let new_str = serde_json::to_string(&payload_val).map_err(|e| {
            WenlanError::Generic(format!("increment_milestone_shown_count serialize: {}", e))
        })?;
        conn.execute(
            "UPDATE onboarding_milestones SET payload = ?1 WHERE id = ?2",
            libsql::params![new_str, id.as_str()],
        )
        .await
        .map_err(|e| {
            WenlanError::VectorDb(format!("increment_milestone_shown_count update: {}", e))
        })?;
        Ok(count)
    }

    /// Clear all milestone rows. Dev/demo-only — exposed via
    /// `POST /api/onboarding/reset` and gated to `import.meta.env.DEV` on
    /// the frontend side.
    pub async fn reset_onboarding_milestones(&self) -> Result<(), WenlanError> {
        let conn = self.conn.lock().await;
        conn.execute("DELETE FROM onboarding_milestones", ())
            .await
            .map_err(|e| WenlanError::VectorDb(format!("reset_onboarding_milestones: {}", e)))?;
        Ok(())
    }

